const ANIM109=PAIJIAN_CONTENT.animations;
const oldVisual109=textbookVisual;
function animationIcon109(kind){return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(kind==='play'?'<path d="m9 5 11 7-11 7z" class="icon-fill"/>':kind==='pause'?'<path d="M9 5v14M16 5v14"/>':'<path d="M19 8a8 8 0 1 0 1 8M19 3v5h-5"/>')+'</svg>'}
textbookVisual=function(kind){const a=ANIM109[kind];if(!a)return oldVisual109(kind);return '<figure class="controlled-animation" data-animation="'+kind+'"><div class="animation-stage" tabindex="0" aria-label="动画画面，移入或轻点显示控制"><div class="animation-frame" role="img" aria-label="'+E(a.caption)+'" style="background-image:url('+a.src+');background-size:'+(a.cols*100)+'% '+(a.rows*100)+'%"></div><div class="animation-overlay"><button type="button" class="animation-icon-button" data-animation-play aria-label="播放动画" title="播放" aria-pressed="false">'+animationIcon109('play')+'</button><button type="button" class="animation-icon-button" data-animation-replay aria-label="重新播放动画" title="重播">'+animationIcon109('replay')+'</button></div></div><figcaption>'+E(a.caption)+'</figcaption></figure>'};
let animationTimers109=[];
function stopAnimations109(){animationTimers109.forEach(clearInterval);animationTimers109=[]}
const priorAnimationBind109=bindReadingPanel;
bindReadingPanel=function(l){stopAnimations109();priorAnimationBind109(l);document.querySelectorAll('[data-animation]').forEach(fig=>{const a=ANIM109[fig.dataset.animation],frame=fig.querySelector('.animation-frame'),play=fig.querySelector('[data-animation-play]');let n=0,timer=null;const draw=()=>{frame.style.backgroundPosition=(n%a.cols)/(a.cols-1)*100+'% '+Math.floor(n/a.cols)/(a.rows-1)*100+'%'};const state=playing=>{play.innerHTML=animationIcon109(playing?'pause':'play');play.setAttribute('aria-label',playing?'暂停动画':'播放动画');play.setAttribute('aria-pressed',String(playing));play.setAttribute('title',playing?'暂停':'播放')};const pause=()=>{if(timer)clearInterval(timer);timer=null;state(false)};const begin=()=>{if(n>=a.count-1)n=0;draw();timer=setInterval(()=>{if(!fig.isConnected){pause();return}n++;draw();if(n>=a.count-1)pause()},180);animationTimers109.push(timer);state(true)};play.onclick=()=>timer?pause():begin();fig.querySelector('[data-animation-replay]').onclick=()=>{pause();n=0;draw();begin()};const stage=fig.querySelector('.animation-stage');stage.onclick=e=>{if(e.target.closest('button'))return;if(typeof matchMedia==='function'&&matchMedia('(hover: none), (pointer: coarse)').matches)stage.classList.toggle('controls-visible')};stage.onkeydown=e=>{if(e.target===stage&&(e.key==='Enter'||e.key===' ')){e.preventDefault();stage.classList.toggle('controls-visible')}};draw();state(false)})};
const priorNavigateAnim109=navigate;navigate=function(t){stopAnimations109();return priorNavigateAnim109(t)};
render();
